function exactProductId(value, graphId) {
  if (typeof value === "string" && /^[1-9]\d{0,19}$/.test(value)) return value;
  if (typeof value === "number" && Number.isInteger(value) && value > 0) {
    if (Number.isSafeInteger(value)) return String(value);
    if (graphId && Number(graphId) === value) return graphId;
  }
  throw new Error("Shopify did not provide an exact parent product ID");
}

function mapProduct(product) {
  const variant = product?.variants?.[0];
  if (!Array.isArray(product?.variants) || !variant || typeof variant !== "object") {
    throw new Error("The Shopify product event has no first variant");
  }
  const graphId =
    typeof product.admin_graphql_api_id === "string"
      ? /^gid:\/\/shopify\/Product\/([1-9]\d{0,19})$/.exec(product.admin_graphql_api_id)?.[1]
      : undefined;
  const productId = exactProductId(variant.product_id, graphId);
  if (
    (graphId && graphId !== productId) ||
    (product.id != null && exactProductId(product.id, graphId) !== productId)
  ) {
    throw new Error("The first Shopify variant belongs to a different parent product");
  }
  if (typeof product.title !== "string" || !product.title.trim()) {
    throw new Error("The Shopify product title is missing");
  }
  const rawPrice = variant.price;
  const price =
    typeof rawPrice === "string" && /^\d+(?:\.\d+)?$/.test(rawPrice.trim())
      ? Number(rawPrice)
      : rawPrice;
  if (!Number.isFinite(price) || price < 0)
    throw new Error("The first Shopify variant has an invalid price");
  const description = product.body_html ?? "";
  if (typeof description !== "string")
    throw new Error("The Shopify product description must be HTML text");
  return {
    productId,
    domain: [["default_code", "=", productId]],
    values: { name: product.title, default_code: productId, description, list_price: price },
  };
}

export default ({ product }) => mapProduct(product);

