function positiveOdooId(id) {
  if (!Number.isSafeInteger(id) || id <= 0)
    throw new Error("Odoo did not confirm a valid record ID");
  return id;
}

function inspectProductLookup(records, productId) {
  if (!Array.isArray(records) || records.length > 1)
    throw new Error("Odoo returned an invalid product search result");
  if (records.length === 0) return { missing: true, result: { state: "missing", productId } };
  const record = records[0];
  if (record?.default_code !== productId)
    throw new Error("Odoo returned a different product reference");
  return {
    missing: false,
    result: { state: "already_exists", productId, odooId: positiveOdooId(record.id) },
  };
}

export default ({ records, productId }) => inspectProductLookup(records, productId);

