export default async function reserve({ productId }, context) {
  const key = "shopify-product:" + productId;
  if (!(await context.state.insert(key, { state: "pending" }))) {
    throw new Error(
      "Odoo product " +
        productId +
        " has a pending create. Check its Odoo Internal Reference before retrying.",
    );
  }
  return { key };
}

