function positiveOdooId(id) {
  if (!Number.isSafeInteger(id) || id <= 0)
    throw new Error("Odoo did not confirm a valid record ID");
  return id;
}

export default async function confirm({ key, productId, id }, context) {
  const odooId = positiveOdooId(id);
  await context.state.delete(key);
  return { result: { state: "created", productId, odooId } };
}

